const bwStaffRef = () => {
  if (!window.__bwStaffRefPromise) {
    window.__bwStaffRefPromise = Promise.all([
      ctx.api.request({ url: 'staff:list', params: { paginate: false, fields: ['id', 'firstName', 'lastName', 'role'] } }),
      ctx.api.request({ url: 'services:list', params: { paginate: false, appends: ['serviceCategory'], fields: ['id', 'name'] } }),
    ]).then(([s, v]) => ({
      staff: (s && s.data && s.data.data) || [],
      services: ((v && v.data && v.data.data) || []).map((x) => ({ id: x.id, name: x.name, category: (x.serviceCategory && x.serviceCategory.name) || 'Uncategorized' })),
    }));
    window.__bwStaffRefPromise.catch(() => { window.__bwStaffRefPromise = null; });
  }
  return window.__bwStaffRefPromise;
};
const bwStaffCache = window.__bwStaffCache || (window.__bwStaffCache = new Map());
const bwHourRow = (r) => {
  const m = /^(\d{4})-(\d{2})-(\d{2}) (\d{1,2})$/.exec(String(r.hour || ''));
  if (!m) throw new Error('Unexpected date format from the server (' + r.hour + ').');
  return { ts: Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4]), amount: Number(r.amount) || 0, count: Number(r.count) || 0, status: r.status, paymentType: r.paymentType, staffId: r.staffId == null ? null : r.staffId };
};
// Four aggregate queries per range: appointments by technician/status, payments by hour/status/type/technician,
// payments without an appointment, and service lines by technician/service/status. Only ids, statuses, counts
// and amounts come back.
const bwFetchStaffData = (from, to) => {
  const key = from + '|' + to;
  const hit = bwStaffCache.get(key);
  if (hit && (hit.pending || Date.now() - hit.at < 60000)) return hit.promise;
  const iso = (ms) => new Date(ms).toISOString();
  const between = (f) => [{ [f]: { $gte: iso(from) } }, { [f]: { $lt: iso(to) } }];
  const q = (url, data) => ctx.api.request({ url, method: 'post', headers: { 'X-Timezone': '+00:00' }, data: Object.assign({ limit: BW_QUERY_LIMIT }, data) })
    .then((res) => { const rows = (res && res.data && res.data.data) || []; if (rows.length >= BW_QUERY_LIMIT) throw new Error('Too much data for this range. Choose a shorter range.'); return rows; });
  const money = [{ field: ['amount'], aggregation: 'sum', alias: 'amount' }, { field: ['id'], aggregation: 'count', alias: 'count' }];
  const payDims = [{ field: ['paymentDate'], format: 'YYYY-MM-DD HH24', alias: 'hour' }, { field: ['status'], alias: 'status' }, { field: ['paymentType'], alias: 'paymentType' }];
  const promise = Promise.all([
    q('appointments:query', { measures: [{ field: ['id'], aggregation: 'count', alias: 'n' }], dimensions: [{ field: ['staffId'], alias: 'staffId' }, { field: ['status'], alias: 'status' }], filter: { $and: between('startTime') } }),
    q('payments:query', { measures: money, dimensions: payDims.concat([{ field: ['appointment', 'staffId'], alias: 'staffId' }]), filter: { $and: between('paymentDate') } }),
    q('payments:query', { measures: money, dimensions: payDims, filter: { $and: between('paymentDate').concat([{ appointmentId: { $empty: true } }]) } }),
    q('appointmentServices:query', { measures: [{ field: ['id'], aggregation: 'count', alias: 'n' }], dimensions: [{ field: ['appointment', 'staffId'], alias: 'staffId' }, { field: ['serviceId'], alias: 'serviceId' }, { field: ['appointment', 'status'], alias: 'status' }], filter: { $and: [{ appointment: { startTime: { $gte: iso(from) } } }, { appointment: { startTime: { $lt: iso(to) } } }] } }),
  ]).then(([appts, pays, noAppt, lines]) => ({ appts, pays: pays.map(bwHourRow), noAppt: noAppt.map(bwHourRow), lines }));
  const entry = { promise, pending: true, at: Date.now() };
  bwStaffCache.set(key, entry);
  promise.then(() => { entry.pending = false; entry.at = Date.now(); }, () => { bwStaffCache.delete(key); });
  return promise;
};

