// Lives inside the BW-STATS block and uses its helpers (h, hooks, Section, Empty, Spin, Alert, Typography, theme,
// bwStaffName) and its filters: the selected range (inst = [from, to) instants in the business time zone) and the
// Technician selector (who). Reviews are filtered by submittedAt, not appointment date.
// Data comes pre-aggregated from customerReviewAdmin:scores (counts, sums and the 1–5 distribution per technician).
// No customer names or comments are loaded here.
function BwReviewStars({ value, size }) {
  const { token } = theme.useToken();
  const px = size || 16;
  const pct = Math.max(0, Math.min(1, Number(value || 0) / 5)) * 100;
  const row = (color) =>
    h('span', { 'aria-hidden': 'true', style: { fontSize: px, letterSpacing: 1, color, whiteSpace: 'nowrap', lineHeight: 1 } }, '★★★★★');
  return h(
    'span',
    { style: { position: 'relative', display: 'inline-block', lineHeight: 1 } },
    row(token.colorBorder),
    h('span', { style: { position: 'absolute', left: 0, top: 0, overflow: 'hidden', width: pct + '%' } }, row('#b07f45')),
  );
}

function BwReviewScores({ inst, who, staff, techs, rangeText, oneCol, reload }) {
  const { token } = theme.useToken();
  const [state, setState] = useState({ loading: true, error: null, data: null });
  const reqId = useRef(0);
  const from = inst ? new Date(inst.from).toISOString() : null;
  const to = inst ? new Date(inst.to).toISOString() : null;
  useEffect(() => {
    if (!from || !to) return;
    const id = ++reqId.current;
    setState((s) => Object.assign({}, s, { loading: true, error: null }));
    ctx.api
      .request({ url: 'customerReviewAdmin:scores', method: 'post', data: { from, to, staffId: who }, skipNotify: true })
      .then(
        (res) => { if (id === reqId.current) setState({ loading: false, error: null, data: (res && res.data && res.data.data) || { staff: [] } }); },
        (err) => {
          if (id !== reqId.current) return;
          const status = err && err.response && err.response.status;
          const msg = status === 404 ? 'Client reviews are not set up (enable @salon/plugin-customer-reviews).'
            : status === 401 || status === 403 ? 'You do not have permission to view client review scores.'
            : (err && err.message) || 'Could not load client review scores.';
          setState({ loading: false, error: msg, data: null });
        });
  }, [from, to, who, reload]);

  const names = useMemo(() => {
    const m = {};
    (staff || []).forEach((s) => { m[String(s.id)] = bwStaffName(s); });
    (techs || []).forEach((t) => { m[String(t.key)] = t.name; });
    return m;
  }, [staff, techs]);

  const sub = 'Average customer rating out of 5, by review submission date' + (rangeText ? ' (' + rangeText + ')' : '') + '. Every submitted review counts, including low and flagged ones.';
  if (!inst) return h(Section, { title: 'Client Review Scores', sub }, h(Typography.Text, { type: 'secondary' }, 'Choose a valid date range.'));
  if (state.error) return h(Section, { title: 'Client Review Scores', sub }, h(Alert, { type: 'warning', showIcon: true, message: state.error }));
  if (state.loading && !state.data) return h(Section, { title: 'Client Review Scores', sub }, h('div', { style: { padding: 16, textAlign: 'center' } }, h(Spin, null)));

  const scores = {};
  ((state.data && state.data.staff) || []).forEach((s) => { scores[String(s.staffId)] = s; });
  const minRankable = (state.data && state.data.minRankable) || 5;
  // Rows: the selected technician, or every technician in the selector plus anyone else who was reviewed.
  let keys;
  if (who && who !== 'all') keys = [String(who)];
  else {
    keys = (techs || []).map((t) => String(t.key));
    Object.keys(scores).forEach((k) => { if (keys.indexOf(k) < 0) keys.push(k); });
  }
  const rows = keys.map((k) => ({ key: k, name: names[k] || 'Staff #' + k, s: scores[k] || null }))
    // Alphabetical, not ranked: a leaderboard from a handful of reviews would mislead.
    .sort((a, b) => a.name.localeCompare(b.name));
  const total = rows.reduce((n, r) => n + (r.s ? r.s.count : 0), 0);
  const sum = rows.reduce((n, r) => n + (r.s ? r.s.sum : 0), 0);
  const fmt1 = (v) => (Math.round(v * 10) / 10).toFixed(1);

  const summary = total
    ? h('div', { style: { display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 10, marginBottom: 12 } },
        h('span', { style: { fontSize: 28, fontWeight: 600, lineHeight: 1 } }, fmt1(sum / total)),
        h(BwReviewStars, { value: sum / total, size: 20 }),
        h('span', { style: { fontSize: 13, color: token.colorTextSecondary } }, 'out of 5 from ' + total + ' review' + (total === 1 ? '' : 's') + (who && who !== 'all' ? '' : ' across all technicians')))
    : null;

  const card = (r) => {
    const s = r.s;
    const box = { border: '1px solid ' + token.colorBorderSecondary, borderRadius: token.borderRadius, padding: '10px 12px', minWidth: 0 };
    if (!s || !s.count) {
      return h('div', { key: r.key, style: box },
        h('div', { style: { fontWeight: 600, overflowWrap: 'anywhere' } }, r.name),
        h('div', { style: { fontSize: 13, color: token.colorTextSecondary, marginTop: 4 } }, 'No reviews yet'));
    }
    const avg = s.sum / s.count;
    const max = Math.max.apply(null, s.distribution);
    return h('div', { key: r.key, style: box, 'aria-label': r.name + ': ' + fmt1(avg) + ' out of 5 from ' + s.count + ' reviews' },
      h('div', { style: { fontWeight: 600, overflowWrap: 'anywhere' } }, r.name),
      h('div', { style: { display: 'flex', alignItems: 'center', flexWrap: 'wrap', gap: 6, marginTop: 4 } },
        h('span', { style: { fontSize: 18, fontWeight: 600 } }, fmt1(avg)),
        h('span', { style: { fontSize: 12, color: token.colorTextSecondary } }, '/ 5'),
        h(BwReviewStars, { value: avg, size: 15 }),
        h('span', { style: { fontSize: 12, color: token.colorTextSecondary } }, '(' + s.count + ' review' + (s.count === 1 ? '' : 's') + ')')),
      s.count < minRankable ? h('div', { style: { fontSize: 11, color: token.colorTextTertiary, marginTop: 2 } }, 'Few reviews: interpret with care') : null,
      s.flagged ? h('div', { style: { fontSize: 11, color: token.colorTextTertiary, marginTop: 2 } }, s.flagged + ' flagged for review (still counted)') : null,
      h('div', { style: { marginTop: 8, display: 'flex', flexDirection: 'column', gap: 2 }, role: 'list', 'aria-label': 'Rating distribution' },
        [5, 4, 3, 2, 1].map((star) => {
          const n = s.distribution[star - 1];
          return h('div', { key: star, role: 'listitem', style: { display: 'flex', alignItems: 'center', gap: 6, fontSize: 11 } },
            h('span', { style: { width: 22, color: token.colorTextSecondary } }, star + '★'),
            h('span', { 'aria-hidden': 'true', style: { flex: 1, height: 6, borderRadius: 3, background: token.colorFillSecondary, overflow: 'hidden' } },
              h('span', { style: { display: 'block', height: '100%', width: (max ? (n / max) * 100 : 0) + '%', background: '#b07f45' } })),
            h('span', { style: { width: 22, textAlign: 'right' } }, String(n)),
            h('span', { className: 'bw-sr', style: { position: 'absolute', width: 1, height: 1, overflow: 'hidden', clip: 'rect(0,0,0,0)' } }, n + ' ' + star + '-star review' + (n === 1 ? '' : 's')));
        })));
  };

  return h(Section, { title: 'Client Review Scores', sub, extra: state.loading ? h(Spin, { size: 'small' }) : null },
    total ? null : h('div', { style: { marginBottom: rows.length ? 10 : 0 } }, h(Empty, { image: Empty.PRESENTED_IMAGE_SIMPLE, description: 'No reviews yet' })),
    summary,
    rows.length && total
      ? h('div', { style: { display: 'grid', gridTemplateColumns: oneCol ? 'minmax(0, 1fr)' : 'repeat(auto-fill, minmax(220px, 1fr))', gap: 8 } }, rows.map(card))
      : null);
}
/* BW-REVIEWS:END */
function StaffPerformance({ inst, range, tz, currency, valid, rangeError, cfg, narrow, oneCol, ctlSize, rangeText, reload, setReload }) {
  const { token } = theme.useToken();
  const [ref, setRef] = useState(null);
  const [state, setState] = useState({ loading: true, error: null, data: null });
  const [who, setWho] = useState('all');
  const reqId = useRef(0);
  useEffect(() => { let off = false; bwStaffRef().then((r) => { if (!off) setRef(r); }, (e) => { if (!off) setState({ loading: false, error: (e && e.message) || 'Could not load staff.', data: null }); }); return () => { off = true; }; }, [reload]);
  useEffect(() => {
    if (!inst) return;
    const id = ++reqId.current;
    setState((s) => Object.assign({}, s, { loading: true, error: null }));
    bwFetchStaffData(inst.from, inst.to).then(
      (data) => { if (id === reqId.current) setState({ loading: false, error: null, data }); },
      (err) => {
        if (id !== reqId.current) return;
        const status = err && err.response && err.response.status;
        setState({ loading: false, error: status === 403 || status === 401 ? 'You do not have permission to view staff statistics.' : ((err && err.message) || 'Could not load staff statistics.'), data: null });
      });
  }, [inst && inst.from, inst && inst.to, reload]);

  const money = (v) => bwMoney(v, currency);
  const d = state.data;
  const calc = useMemo(() => {
    if (!d || !ref || !valid) return null;
    const counts = bwAppointmentCounts(d.appts);
    const rev = bwStaffRevenue(d.pays, d.noAppt, { start: range.start, end: range.end, tz });
    const active = Object.keys(counts).concat(Object.keys(rev.by)).filter((k) => k !== BW_UNASSIGNED);
    const techs = bwTechnicians(ref.staff, active);
    const zero = { total: 0, completed: 0, cancelled: 0, noShow: 0, upcoming: 0 };
    const zr = { net: 0, gross: 0, refunds: 0, tx: 0 };
    const rows = techs.map((t) => {
      const c = counts[t.key] || zero; const r = rev.by[t.key] || zr;
      return { key: t.key, name: t.name, c, rev: r, completed: c.completed, avg: c.completed ? Math.round((r.net / c.completed) * 100) / 100 : null };
    });
    const unassigned = { key: BW_UNASSIGNED, name: 'No technician assigned', c: counts[BW_UNASSIGNED] || zero };
    return { counts, rev, techs, rows, unassigned };
  }, [d, ref, valid && range.start, valid && range.end, tz]);

  // Technician selector: All staff or one technician (applies to every section).
  const techOptions = [{ label: 'All staff', value: 'all' }].concat(((calc && calc.techs) || (ref ? bwTechnicians(ref.staff, []) : [])).map((t) => ({ label: t.name, value: t.key })));
  const selector = h('label', { style: { display: 'flex', flexDirection: narrow ? 'column' : 'row', alignItems: narrow ? 'stretch' : 'center', gap: narrow ? 4 : 8, fontSize: 12, color: token.colorTextSecondary, minWidth: 0 } },
    'Technician',
    h(Select, { value: who, onChange: setWho, options: techOptions, size: ctlSize, style: { minWidth: narrow ? 0 : 200, width: narrow ? '100%' : undefined }, 'aria-label': 'Technician', showSearch: true, optionFilterProp: 'label' }));
  const pick = (rows) => (who === 'all' ? rows : rows.filter((r) => r.key === who));

  let body;
  if (!cfg || !ref && !state.error) body = h(Card, null, h('div', { style: { height: 160, display: 'flex', alignItems: 'center', justifyContent: 'center' } }, h(Spin, null)));
  else if (!valid) body = h(Card, null, h(Empty, { image: Empty.PRESENTED_IMAGE_SIMPLE, description: rangeError || 'Choose a date range' }));
  else if (state.error) body = h(Card, null, h(Alert, { type: 'error', showIcon: true, message: 'Could not load staff statistics', description: state.error,
    action: h(Button, { size: narrow ? 'middle' : 'small', onClick: () => { bwStaffCache.clear(); window.__bwStaffRefPromise = null; setReload((x) => x + 1); } }, 'Retry') }));
  else if (state.loading || !calc) body = h(Card, null, h('div', { style: { height: 160, display: 'flex', alignItems: 'center', justifyContent: 'center' } }, h(Spin, null)));
  else {
    const rows = pick(calc.rows);
    const sel = who === 'all' ? null : calc.rows.find((r) => r.key === who);
    const demand = bwSkillDemand(d.lines, ref.services, who);
    const apptTotal = rows.reduce((a, r) => a + r.c.total, 0);
    const completedTotal = rows.reduce((a, r) => a + r.c.completed, 0);
    const revRows = rows.slice().sort((a, b) => b.rev.net - a.rev.net || a.name.localeCompare(b.name));
    // Highest revenue: largest net; ties go to the alphabetically first name. None when nobody earned.
    const best = calc.rows.filter((r) => r.rev.net > 0).sort((a, b) => b.rev.net - a.rev.net || a.name.localeCompare(b.name))[0] || null;
    const revenueShown = rows.reduce((a, r) => a + r.rev.net, 0);
    const R = calc.rev;
    const cols = oneCol ? 'minmax(0, 1fr)' : narrow ? 'repeat(2, minmax(0, 1fr))' : 'repeat(auto-fit, minmax(170px, 1fr))';
    const cards = h('div', { style: { display: 'grid', gridTemplateColumns: cols, gap: narrow ? 8 : 12 } },
      h(Metric, { strong: true, compact: oneCol, style: narrow && !oneCol ? { gridColumn: '1 / -1' } : null, label: sel ? sel.name + ' · revenue' : 'Revenue by technicians', value: money(revenueShown), sub: sel ? sel.rev.tx + ' paid payments' : 'of ' + money(R.total.net) + ' total earnings' }),
      h(Metric, { compact: oneCol, label: 'Appointments', value: String(apptTotal), sub: completedTotal + ' completed' }),
      h(Metric, { compact: oneCol, label: 'Avg per completed appointment', value: completedTotal ? money(Math.round((revenueShown / completedTotal) * 100) / 100) : '—', sub: 'Revenue ÷ completed appointments' }),
      h(Metric, { compact: oneCol, accent: best ? token.colorWarningText : token.colorTextTertiary, label: sel ? 'Most booked service' : 'Highest revenue', value: sel ? (demand.services[0] ? demand.services[0].name : 'No bookings') : (best ? best.name : 'No revenue yet'), sub: sel ? (demand.services[0] ? demand.services[0].n + ' bookings' : '') : (best ? money(best.rev.net) : '') }));

    const apptRows = who === 'all' && calc.unassigned.c.total ? rows.concat([calc.unassigned]) : rows;
    const appointments = h(Section, { title: 'Appointments per technician', sub: 'By appointment date in the selected range' + (who === 'all' && calc.unassigned.c.total ? '. ' + calc.unassigned.c.total + ' appointment' + (calc.unassigned.c.total === 1 ? ' has' : 's have') + ' no technician assigned.' : '.') },
      apptRows.length ? h(AppointmentBars, { rows: apptRows }) : h(Empty, { image: Empty.PRESENTED_IMAGE_SIMPLE, description: 'No technicians' }));

    const unattributed = R.noAppointment.net + R.unassignedAppointment.net;
    const reconcile = who === 'all' ? h('div', { style: { fontSize: 12, color: token.colorTextSecondary, marginTop: 12, lineHeight: 1.5 } },
      'Total earnings ' + money(R.total.net) + ' = technicians ' + money(R.attributed.net) + ' + not attributed ' + money(unattributed) +
      (unattributed ? ' (' + [R.unassignedAppointment.net ? money(R.unassignedAppointment.net) + ' on appointments with no technician' : null, R.noAppointment.net ? money(R.noAppointment.net) + ' not linked to an appointment, such as memberships' : null].filter(Boolean).join('; ') + ')' : '') + '.') : null;
    const revenue = h(Section, { title: 'Revenue per technician', sub: 'Paid payments minus refunds, by payment date, credited to the appointment’s technician' },
      revRows.length && revRows.some((r) => r.rev.net || r.rev.tx) ? h(RevenueBars, { rows: revRows, best, currency }) : h(Empty, { image: Empty.PRESENTED_IMAGE_SIMPLE, description: 'No revenue between ' + rangeText + '.' }),
      reconcile);

    const topCat = demand.categories[0];
    const perTech = who === 'all' ? calc.rows.filter((r) => demand.byStaff[r.key]).map((r) => ({ name: r.name, st: demand.byStaff[r.key] })) : [];
    const skills = h(Section, { title: 'Skill demand', sub: 'Services booked on appointments in the range (cancelled and no-show appointments excluded)' + (sel ? ' for ' + sel.name : '') },
      demand.total ? h('div', { style: { display: 'flex', flexDirection: 'column', gap: 14 } },
        h('div', { style: { fontSize: 13 } }, 'Most booked: ', h('strong', null, demand.services[0].name), ' (' + demand.services[0].n + ')', topCat ? h('span', null, ' · Top category: ', h('strong', null, topCat.name), ' (' + topCat.n + ')') : null),
        h(RankedList, { items: demand.services, total: demand.total, label: 'booking' }),
        perTech.length ? h('div', { style: { display: 'grid', gridTemplateColumns: oneCol ? 'minmax(0, 1fr)' : 'repeat(auto-fill, minmax(220px, 1fr))', gap: 8 } },
          perTech.map((p) => h('div', { key: p.name, style: { border: '1px solid ' + token.colorBorderSecondary, borderRadius: token.borderRadius, padding: '8px 10px', minWidth: 0, fontSize: 12 } },
            h('div', { style: { fontWeight: 600, fontSize: 13, overflowWrap: 'anywhere' } }, p.name),
            h('div', { style: { color: token.colorTextSecondary } }, p.st.n + ' bookings'),
            h('div', { style: { overflowWrap: 'anywhere' } }, 'Top service: ' + p.st.topService.name + ' (' + p.st.topService.n + ')'),
            h('div', { style: { overflowWrap: 'anywhere' } }, 'Top category: ' + p.st.topCategory.name + ' (' + p.st.topCategory.n + ')')))) : null)
        : h(Empty, { image: Empty.PRESENTED_IMAGE_SIMPLE, description: 'No services booked between ' + rangeText + (sel ? ' for ' + sel.name : '') + '.' }));
    body = h('div', { style: { display: 'flex', flexDirection: 'column', gap: 12, minWidth: 0 } }, cards, appointments, revenue, skills);
  }
  return h('div', { style: { display: 'flex', flexDirection: 'column', gap: 12, minWidth: 0 } },
    h(Card, null, selector), body, h(BwReviewScores, { inst, who, staff: ref ? ref.staff : [], techs: (calc && calc.techs) || (ref ? bwTechnicians(ref.staff, []) : []), rangeText, oneCol, reload }),
    h(Typography.Text, { type: 'secondary', style: { fontSize: 12 } },
      'Each appointment has one technician, so its services and payments are credited to that technician; nothing is split. Appointments count by appointment date; revenue by payment date, using the Earnings rules (paid payments minus refunds; pending, failed and refunded payments excluded). Average per completed appointment = revenue ÷ completed appointments in the same range. Skill demand counts each booked service once. Office staff (receptionist, admin, manager) appear only when they have appointments.'));
}

// The Earnings and Client Retention tabs share one date selection for the browser session.
const BW_RANGE_KEY = 'bwStatsRange';
const bwRangeListeners = window.__bwStatsRangeListeners || (window.__bwStatsRangeListeners = new Set());
const bwReadRange = () => { try { const v = JSON.parse(window.sessionStorage.getItem(BW_RANGE_KEY) || 'null'); if (v && PRESETS.some((p) => p.value === v.preset)) return v; } catch (e) { /* storage unavailable */ } return null; };
const bwSaveRange = (v) => {
  try { window.sessionStorage.setItem(BW_RANGE_KEY, JSON.stringify(v)); } catch (e) { /* storage unavailable */ }
  const detail = { preset: v.preset, custom: { start: v.custom.start, end: v.custom.end }, from: BW_VIEW };
  bwRangeListeners.forEach((fn) => { try { fn(detail); } catch (e) { /* ignore a closed tab */ } });
};

function Statistics() {
  const { token } = theme.useToken();
  const [cfg, setCfg] = useState(null);
  const saved = useMemo(() => bwReadRange(), []);
  const [preset, setPreset] = useState((saved && saved.preset) || 'thisMonth');
  const [grouping, setGrouping] = useState('day');
  const [custom, setCustom] = useState((saved && saved.custom) || { start: null, end: null });
  useEffect(() => { bwSaveRange({ preset, custom }); }, [preset, custom.start, custom.end]);
  // Follow a range picked on the other tab.
  useEffect(() => {
    const onRange = (v) => {
      if (v.from === BW_VIEW) return;
      if (v.preset) setPreset((p) => (p === v.preset ? p : v.preset));
      if (v.custom) setCustom((c) => (c.start === v.custom.start && c.end === v.custom.end ? c : { start: v.custom.start, end: v.custom.end }));
    };
    bwRangeListeners.add(onRange);
    return () => { bwRangeListeners.delete(onRange); };
  }, []);
  const [state, setState] = useState({ loading: true, error: null, entries: [] });
  const [reload, setReload] = useState(0);
  const reqId = useRef(0);
  const rootRef = useRef(null);
  const rootW = useWidth(rootRef);
  const narrow = rootW > 0 && rootW < 560;
  // Card columns by the width this block actually has (works inside NocoBase's own layout):
  // 1 column on small phones, 2 on larger phones and tablets, the original auto-fit grid on desktop.
  const oneCol = rootW > 0 && rootW < 360;
  const earnCols = oneCol ? 1 : rootW > 0 && rootW < 716 ? 2 : 0;
  const retCols = oneCol ? 1 : rootW > 0 && rootW < 624 ? 2 : 0;
  // Phones and tablets (block narrower than the 4-card desktop row) get touch-sized controls.
  const touch = rootW > 0 && rootW < 716;
  const ctlSize = touch ? 'large' : undefined;
  useEffect(() => { let off = false; bwLoadConfig().then((c) => { if (!off) setCfg(c); }); return () => { off = true; }; }, []);

  const tz = (cfg && cfg.timeZone) || BW_DEFAULTS.timeZone;
  const currency = (cfg && cfg.currency) || BW_DEFAULTS.currency;
  const weekStart = cfg ? cfg.weekStart : BW_WEEK_START;
  const today = bwPartsIn(Date.now(), tz).ymd;
  const range = preset === 'custom' ? (custom.start && custom.end ? { start: custom.start, end: custom.end } : null) : bwPresetRange(preset, today, weekStart);
  const rangeError = preset === 'custom' ? (custom.start || custom.end ? bwValidateRange(custom.start, custom.end) : 'Choose a start date and an end date.') : '';
  const valid = !!cfg && !!range && !rangeError;
  const inst = valid ? bwRangeInstants(range.start, range.end, tz) : null;

  useEffect(() => {
    if (!inst || BW_VIEW !== 'earnings') return;
    const id = ++reqId.current;
    setState((s) => Object.assign({}, s, { loading: true, error: null }));
    bwFetchEntries(inst.from, inst.to).then(
      (entries) => { if (id === reqId.current) setState({ loading: false, error: null, entries }); },
      (err) => {
        if (id !== reqId.current) return;
        const status = err && err.response && err.response.status;
        const msg = status === 403 || status === 401 ? 'You do not have permission to view earnings.' : ((err && err.response && err.response.data && err.response.data.errors && err.response.data.errors[0] && err.response.data.errors[0].message) || (err && err.message) || 'Could not load earnings.');
        setState({ loading: false, error: msg, entries: [] });
      });
  }, [inst && inst.from, inst && inst.to, reload]);

  // ----- client retention for the same range, plus the comparison window -----
  const prevRange = valid ? bwPreviousRange(preset, range) : null;
  const prevInst = prevRange ? bwRangeInstants(prevRange.start, prevRange.end, tz) : null;
  const [clients, setClients] = useState({ loading: true, error: null, cur: null, prev: null });
  const clientReq = useRef(0);
  useEffect(() => {
    if (!inst || !prevInst || BW_VIEW !== 'clients') return;
    const id = ++clientReq.current;
    setClients((s) => Object.assign({}, s, { loading: true, error: null }));
    Promise.all([bwFetchClientRows(inst.to), bwFetchClientRows(prevInst.to)]).then(
      ([curRows, prevRows]) => {
        if (id !== clientReq.current) return;
        setClients({ loading: false, error: null, cur: bwClassify(curRows, inst.from, inst.to), prev: bwClassify(prevRows, prevInst.from, prevInst.to) });
      },
      (err) => {
        if (id !== clientReq.current) return;
        const status = err && err.response && err.response.status;
        setClients({ loading: false, error: status === 403 || status === 401 ? 'You do not have permission to view client statistics.' : ((err && err.message) || 'Could not load client statistics.'), cur: null, prev: null });
