// BW-STATS v5 – Statistics page (one source, three tabs): earnings, new vs returning clients, and staff performance (server-side aggregation). Mobile-responsive.
// Source: scratchpad stats/core.js + retention-core.js + staff-core.js (tested) + block-ui.js. BW_VIEW picks the tab.
const BW_VIEW = 'earnings';
// BW-STATS core v1 – pure revenue logic shared by the Statistics block and the tests.
// No NocoBase or React dependencies. Dates are business-calendar strings 'YYYY-MM-DD'.

// ---------- time zone helpers ----------
const bwPartsIn = (ms, tz) => {
  const p = {};
  new Intl.DateTimeFormat('en-US', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' })
    .formatToParts(new Date(ms)).forEach((x) => { p[x.type] = x.value; });
  return { ymd: p.year + '-' + p.month + '-' + p.day, hour: Number(p.hour) % 24, minute: Number(p.minute) };
};
// The instant when the business clock shows ymd 00:00 (handles DST).
const bwStartOfDay = (ymd, tz) => {
  const [y, m, d] = ymd.split('-').map(Number);
  const want = Date.UTC(y, m - 1, d);
  let guess = want;
  for (let i = 0; i < 4; i += 1) {
    const p = bwPartsIn(guess, tz);
    const [py, pm, pd] = p.ymd.split('-').map(Number);
    const seen = Date.UTC(py, pm - 1, pd, p.hour, p.minute);
    if (seen === want) break;
    guess += want - seen;
  }
  return guess;
};

// ---------- calendar helpers (pure date strings, no time zone) ----------
const bwYmd = (dt) => dt.toISOString().slice(0, 10);
const bwParse = (ymd) => { const [y, m, d] = ymd.split('-').map(Number); return new Date(Date.UTC(y, m - 1, d)); };
const bwAddDays = (ymd, n) => { const dt = bwParse(ymd); dt.setUTCDate(dt.getUTCDate() + n); return bwYmd(dt); };
const bwDow = (ymd) => bwParse(ymd).getUTCDay(); // 0 = Sunday
const BW_WEEK_START = 1; // Monday (ISO week)
const bwWeekStart = (ymd, weekStart = BW_WEEK_START) => bwAddDays(ymd, -((bwDow(ymd) - weekStart + 7) % 7));
const bwMonthStart = (ymd) => ymd.slice(0, 8) + '01';
const bwMonthEnd = (ymd) => { const dt = bwParse(bwMonthStart(ymd)); dt.setUTCMonth(dt.getUTCMonth() + 1); dt.setUTCDate(0); return bwYmd(dt); };
const bwMax = (a, b) => (a > b ? a : b);
const bwMin = (a, b) => (a < b ? a : b);

// ---------- date range presets ----------
// today: the business date right now. Returns inclusive { start, end } business dates.
const bwPresetRange = (preset, today, weekStart = BW_WEEK_START) => {
  if (preset === 'thisWeek') return { start: bwWeekStart(today, weekStart), end: today };
  if (preset === 'thisMonth') return { start: bwMonthStart(today), end: today };
  if (preset === 'lastMonth') { const end = bwAddDays(bwMonthStart(today), -1); return { start: bwMonthStart(end), end }; }
  return null;
};
const bwValidateRange = (start, end) => {
  const ok = (s) => typeof s === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(s);
  if (!ok(start) || !ok(end)) return 'Choose a start date and an end date.';
  if (start > end) return 'The start date must be on or before the end date.';
  return '';
};
// Inclusive business dates -> half-open UTC instants [from, to) for the database filter.
const bwRangeInstants = (start, end, tz) => ({ from: bwStartOfDay(start, tz), to: bwStartOfDay(bwAddDays(end, 1), tz) });

// ---------- revenue model ----------
// One entry is a payment, or an aggregate of payments sharing status/type within one UTC hour:
//   { ts (ms), amount (sum), count, status, paymentType }
// Rules (payments are the source of truth):
//   status 'paid', type other than 'refund'  -> + amount, counted as a revenue transaction
//   status 'paid', type 'refund'             -> − |amount| (money returned), not a transaction
//   status 'refunded'                        -> 0 (the payment was reversed in full)
//   status 'pending' / 'failed' / other      -> 0
const bwContribution = (e) => {
  const amt = Number(e.amount) || 0;
  if (e.status !== 'paid') return { net: 0, gross: 0, refunds: 0, tx: 0 };
  if (e.paymentType === 'refund') return { net: -Math.abs(amt), gross: 0, refunds: Math.abs(amt), tx: 0 };
  return { net: amt, gross: amt, refunds: 0, tx: Number(e.count == null ? 1 : e.count) || 0 };
};

const bwFmtShort = (ymd) => bwParse(ymd).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
const bwFmtRange = (a, b) => {
  if (a === b) return bwFmtShort(a);
  const A = bwParse(a); const B = bwParse(b);
  const yA = A.getUTCFullYear(); const yB = B.getUTCFullYear();
  if (yA !== yB) return bwFmtShort(a) + ', ' + yA + ' – ' + bwFmtShort(b) + ', ' + yB;
  if (A.getUTCMonth() === B.getUTCMonth()) return bwFmtShort(a) + '–' + B.getUTCDate();
  return bwFmtShort(a) + ' – ' + bwFmtShort(b);
};
// A range with its year, written once: 'Oct 5–11, 2026' or 'Dec 29, 2025 – Jan 4, 2026'.
const bwFmtRangeYear = (a, b) => (a.slice(0, 4) !== b.slice(0, 4) ? bwFmtRange(a, b) : bwFmtRange(a, b) + ', ' + b.slice(0, 4));
const bwFmtMonth = (ymd) => bwParse(ymd).toLocaleDateString('en-US', { month: 'short', year: 'numeric', timeZone: 'UTC' });

// Every period that overlaps [start, end], clipped to the range, in chronological order.
const bwPeriods = (start, end, grouping, weekStart = BW_WEEK_START) => {
  const out = [];
  if (grouping === 'day') {
    for (let d = start; d <= end; d = bwAddDays(d, 1)) out.push({ key: d, from: d, to: d, label: bwFmtShort(d), longLabel: bwParse(d).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' }) });
  } else if (grouping === 'week') {
    for (let w = bwWeekStart(start, weekStart); w <= end; w = bwAddDays(w, 7)) {
      const from = bwMax(w, start); const to = bwMin(bwAddDays(w, 6), end);
      out.push({ key: w, from, to, partial: from !== w || to !== bwAddDays(w, 6), label: bwFmtRange(from, to), longLabel: 'Week of ' + bwFmtRangeYear(from, to) });
    }
  } else {
    for (let m = bwMonthStart(start); m <= end; m = bwAddDays(bwMonthEnd(m), 1)) {
      const from = bwMax(m, start); const to = bwMin(bwMonthEnd(m), end);
      const full = from === m && to === bwMonthEnd(m);
      out.push({ key: m.slice(0, 7), from, to, partial: !full, label: bwFmtMonth(m), longLabel: full ? bwParse(m).toLocaleDateString('en-US', { month: 'long', year: 'numeric', timeZone: 'UTC' }) : bwFmtRangeYear(from, to) });
    }
  }
  return out;
};

// entries -> { periods (with net/gross/refunds/tx), totals, best }
const bwAggregate = (entries, { start, end, grouping, tz, weekStart = BW_WEEK_START }) => {
  const periods = bwPeriods(start, end, grouping, weekStart).map((p) => Object.assign(p, { net: 0, gross: 0, refunds: 0, tx: 0 }));
  const keyOf = (ymd) => (grouping === 'day' ? ymd : grouping === 'week' ? bwWeekStart(ymd, weekStart) : ymd.slice(0, 7));
  const index = new Map(periods.map((p) => [p.key, p]));
  const totals = { net: 0, gross: 0, refunds: 0, tx: 0, outside: 0 };
  for (const e of entries) {
    const ymd = bwPartsIn(e.ts, tz).ymd;
    if (ymd < start || ymd > end) { totals.outside += 1; continue; } // never count anything outside the range
    const c = bwContribution(e);
    const p = index.get(keyOf(ymd));
    if (!p) { totals.outside += 1; continue; }
    p.net += c.net; p.gross += c.gross; p.refunds += c.refunds; p.tx += c.tx;
    totals.net += c.net; totals.gross += c.gross; totals.refunds += c.refunds; totals.tx += c.tx;
  }
  const round = (x) => Math.round(x * 100) / 100;
  periods.forEach((p) => { p.net = round(p.net); p.gross = round(p.gross); p.refunds = round(p.refunds); });
  ['net', 'gross', 'refunds'].forEach((k) => { totals[k] = round(totals[k]); });
  totals.average = totals.tx > 0 ? round(totals.net / totals.tx) : 0;
  // Highest-grossing period: largest net earnings; ties go to the earliest period. None when nothing was earned.
  let best = null;
  for (const p of periods) if (p.net > 0 && (!best || p.net > best.net)) best = p;
  return { periods, totals, best };
};

const bwMoney = (n, currency = 'USD') => new Intl.NumberFormat('en-US', { style: 'currency', currency, minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(Number(n) || 0);
const bwMoneyShort = (n, currency = 'USD') => {
  const v = Number(n) || 0;
  if (Math.abs(v) >= 1000) return new Intl.NumberFormat('en-US', { style: 'currency', currency, notation: 'compact', maximumFractionDigits: 1 }).format(v);
  return new Intl.NumberFormat('en-US', { style: 'currency', currency, maximumFractionDigits: 0 }).format(v);
};

// ---------- client retention (new vs returning) ----------
// A qualifying appointment is one with status 'completed' – the same rule the CRM already uses for
// customers.firstVisitAt / visitCount (Refresh customer activity). Scheduled, confirmed, in-progress,
// cancelled and no-show appointments never qualify. Appointments without a customer are ignored.
const BW_QUALIFYING_STATUSES = ['completed'];

// The comparison window just before the selected range.
//   This Week / This Month: the previous week / month, cut to the same number of elapsed days.
//   Last Month: the month before it.  Custom: the same number of days immediately before.
const bwPreviousRange = (preset, range) => {
  const days = Math.round((bwParse(range.end) - bwParse(range.start)) / 86400000) + 1;
  if (preset === 'thisWeek') return { start: bwAddDays(range.start, -7), end: bwAddDays(range.start, -7 + days - 1) };
  if (preset === 'thisMonth' || preset === 'lastMonth') {
    const prevEnd = bwAddDays(range.start, -1);
    const start = bwMonthStart(prevEnd);
    if (preset === 'lastMonth') return { start, end: prevEnd };
    const want = bwAddDays(start, days - 1);
    return { start, end: want < prevEnd ? want : prevEnd };
  }
  return { start: bwAddDays(range.start, -days), end: bwAddDays(range.start, -1) };
};

// rows: one per customer, { customerId, first, last } where first/last are the earliest / latest qualifying
// appointment start (ms) before the end of the range. Counts each customer once.
const bwClassify = (rows, from, to) => {
  let nNew = 0; let nReturning = 0;
  for (const r of rows) {
    if (r.customerId == null || r.customerId === '') continue;
    if (!(r.last >= from && r.last < to)) continue; // no qualifying appointment inside the range
    if (r.first >= from) nNew += 1; else nReturning += 1;
  }
  const total = nNew + nReturning;
  const pct = (n) => (total > 0 ? Math.round((n / total) * 1000) / 10 : null);
  return { total, newClients: nNew, returning: nReturning, newPct: pct(nNew), returningPct: pct(nReturning) };
};

// Same rows built from raw appointment records (used by the tests and the live cross-check).
const bwRowsFromAppointments = (appts, to) => {
  const by = new Map();
  for (const a of appts) {
    if (!BW_QUALIFYING_STATUSES.includes(a.status) || a.customerId == null || a.customerId === '') continue;
    const ts = new Date(a.startTime).getTime();
    if (!(ts < to)) continue;
    const r = by.get(a.customerId) || { customerId: a.customerId, first: Infinity, last: -Infinity };
    r.first = Math.min(r.first, ts); r.last = Math.max(r.last, ts);
    by.set(a.customerId, r);
  }
  return [...by.values()];
};

// Change in a count versus the previous period. pct is null when the previous count is 0.
const bwChange = (cur, prev) => ({ diff: cur - prev, pct: prev > 0 ? Math.round(((cur - prev) / prev) * 1000) / 10 : null });

// ---------- staff performance (T-01 data layer) ----------
// Attribution: each appointment has exactly one technician (appointments.staffId); appointment service
// lines have no technician of their own, so every service line and every payment linked to an appointment
// belongs to that appointment's technician. Nothing is split between technicians.
// Records without a technician are kept in an "Unassigned" bucket and never dropped.
const BW_NON_TECH_ROLES = ['receptionist', 'admin', 'manager'];
const BW_UNASSIGNED = '__unassigned';
const BW_UPCOMING = ['scheduled', 'confirmed', 'inProgress'];
// Skill demand counts services on appointments that were not cancelled and not no-shows.
const BW_DEMAND_STATUSES = ['scheduled', 'confirmed', 'inProgress', 'completed'];

const bwStaffName = (s) => [s.firstName, s.lastName].filter(Boolean).join(' ').trim() || 'Staff #' + s.id;
const bwKey = (id) => (id == null || id === '' ? BW_UNASSIGNED : String(id));

// Technicians: everyone whose role is not receptionist/admin/manager, plus anyone with activity in the
// range (so nothing is hidden). Staff with zero activity are still listed (zero rows).
const bwTechnicians = (staff, activeIds) => {
  const active = new Set((activeIds || []).map(String));
  return staff
    .filter((s) => !BW_NON_TECH_ROLES.includes(String(s.role || '').toLowerCase()) || active.has(String(s.id)))
    .map((s) => ({ key: String(s.id), name: bwStaffName(s), role: s.role || '' }))
    .sort((a, b) => a.name.localeCompare(b.name));
};

// rows: { staffId, status, n } (one per technician + status) -> per-technician appointment counts.
const bwAppointmentCounts = (rows) => {
  const by = {};
  for (const r of rows) {
    const k = bwKey(r.staffId);
    const c = by[k] || (by[k] = { total: 0, completed: 0, cancelled: 0, noShow: 0, upcoming: 0 });
    const n = Number(r.n) || 0;
    c.total += n;
    if (r.status === 'completed') c.completed += n;
    else if (r.status === 'cancelled') c.cancelled += n;
    else if (r.status === 'noShow') c.noShow += n;
    else if (BW_UPCOMING.includes(r.status)) c.upcoming += n;
  }
  return by;
};

// entries: { ts, amount, count, status, paymentType, staffId } (hour buckets) and noAppt: the same rows for
// payments with no appointment at all (memberships etc.). Uses the Earnings rules (bwContribution).
const bwStaffRevenue = (entries, noAppt, { start, end, tz }) => {
  const inRange = (e) => { const d = bwPartsIn(e.ts, tz).ymd; return d >= start && d <= end; };
  const add = (acc, e) => { const c = bwContribution(e); acc.net += c.net; acc.gross += c.gross; acc.refunds += c.refunds; acc.tx += c.tx; return acc; };
  const z = () => ({ net: 0, gross: 0, refunds: 0, tx: 0 });
  const by = {}; const total = z();
  for (const e of entries) { if (!inRange(e)) continue; add(by[bwKey(e.staffId)] || (by[bwKey(e.staffId)] = z()), e); add(total, e); }
  const noAppointment = z();
  for (const e of noAppt) if (inRange(e)) add(noAppointment, e);
  const round = (o) => { ['net', 'gross', 'refunds'].forEach((k) => { o[k] = Math.round(o[k] * 100) / 100; }); return o; };
  Object.values(by).forEach(round); round(total); round(noAppointment);
  const un = by[BW_UNASSIGNED] || z();
  // Unattributed = payments with no appointment + payments on appointments without a technician.
  const unassignedAppointment = round({ net: un.net - noAppointment.net, gross: un.gross - noAppointment.gross, refunds: un.refunds - noAppointment.refunds, tx: un.tx - noAppointment.tx });
  const attributed = round(Object.entries(by).filter(([k]) => k !== BW_UNASSIGNED).reduce((a, [, v]) => { a.net += v.net; a.gross += v.gross; a.refunds += v.refunds; a.tx += v.tx; return a; }, z()));
  return { by, total, attributed, noAppointment, unassignedAppointment };
};

// rows: { staffId, serviceId, status, n } service lines; services: [{ id, name, category }].
// Counts service bookings (lines), not appointments, on non-cancelled, non-no-show appointments.
const bwSkillDemand = (rows, services, staffKey) => {
  const svc = new Map(services.map((s) => [String(s.id), s]));
  const byService = {}; const byCategory = {}; const byStaff = {};
  for (const r of rows) {
    if (!BW_DEMAND_STATUSES.includes(r.status)) continue;
    const k = bwKey(r.staffId);
    if (staffKey && staffKey !== 'all' && k !== staffKey) continue;
    const s = svc.get(String(r.serviceId)) || { id: r.serviceId, name: 'Unknown service', category: 'Uncategorized' };
    const n = Number(r.n) || 0;
    const sk = String(s.id);
    (byService[sk] = byService[sk] || { id: sk, name: s.name, category: s.category || 'Uncategorized', n: 0 }).n += n;
    const ck = s.category || 'Uncategorized';
    (byCategory[ck] = byCategory[ck] || { name: ck, n: 0 }).n += n;
    const st = byStaff[k] || (byStaff[k] = { services: {}, categories: {}, n: 0 });
    st.n += n; st.services[s.name] = (st.services[s.name] || 0) + n; st.categories[ck] = (st.categories[ck] || 0) + n;
  }
  // Ties: alphabetical, so the result does not depend on query order.
  const rank = (arr) => arr.sort((a, b) => b.n - a.n || a.name.localeCompare(b.name));
  const top = (o) => { const e = Object.entries(o).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))[0]; return e ? { name: e[0], n: e[1] } : null; };
  Object.values(byStaff).forEach((st) => { st.topService = top(st.services); st.topCategory = top(st.categories); });
  return { services: rank(Object.values(byService)), categories: rank(Object.values(byCategory)), byStaff, total: Object.values(byService).reduce((a, s) => a + s.n, 0) };
};

// ---------- data loading (server-side aggregation, de-duplicated) ----------
const BW_DEFAULTS = { timeZone: 'America/Chicago', currency: 'USD', weekStart: BW_WEEK_START };
const bwLoadConfig = () => {
  if (!window.__bwStatsConfigPromise) {
    window.__bwStatsConfigPromise = ctx.api.request({ url: 'systemSettings:get' })
      .then((res) => {
        const o = (res && res.data && res.data.data && res.data.data.options) || {};
        const bh = o.bwBusinessHours || {};
        const st = o.bwStatistics || {};
        return { timeZone: bh.timeZone || BW_DEFAULTS.timeZone, currency: st.currency || BW_DEFAULTS.currency, weekStart: st.weekStart != null ? Number(st.weekStart) : BW_DEFAULTS.weekStart };
      })
      .catch(() => BW_DEFAULTS);
  }
  return window.__bwStatsConfigPromise;
};
// Rows come back already summed by the database: one row per UTC hour, payment status and payment type.
// Only amounts and counts are requested, never customer or payment details.
const BW_QUERY_LIMIT = 20000;
const bwCache = window.__bwStatsCache || (window.__bwStatsCache = new Map());
const bwFetchEntries = (from, to) => {
  const key = from + '|' + to;
  const hit = bwCache.get(key);
  if (hit && (hit.pending || Date.now() - hit.at < 60000)) return hit.promise;
  const filter = { $and: [{ paymentDate: { $gte: new Date(from).toISOString() } }, { paymentDate: { $lt: new Date(to).toISOString() } }] };
  const promise = ctx.api.request({
    url: 'payments:query',
    method: 'post',
    headers: { 'X-Timezone': '+00:00' },
    data: {
      measures: [{ field: ['amount'], aggregation: 'sum', alias: 'amount' }, { field: ['id'], aggregation: 'count', alias: 'count' }],
      dimensions: [{ field: ['paymentDate'], format: 'YYYY-MM-DD HH24', alias: 'hour' }, { field: ['status'], alias: 'status' }, { field: ['paymentType'], alias: 'paymentType' }],
      filter,
      limit: BW_QUERY_LIMIT,
    },
  }).then((res) => {
    const rows = (res && res.data && res.data.data) || [];
    if (rows.length >= BW_QUERY_LIMIT) throw new Error('Too much data for this range. Choose a shorter range.');
    return rows.map((r) => {
      const m = /^(\d{4})-(\d{2})-(\d{2}) (\d{1,2})$/.exec(String(r.hour || ''));
      if (!m) throw new Error('Unexpected date format from the server (' + r.hour + ').');
      return { ts: Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4]), amount: Number(r.amount) || 0, count: Number(r.count) || 0, status: r.status, paymentType: r.paymentType };
    });
  });
  const entry = { promise, pending: true, at: Date.now() };
  bwCache.set(key, entry);
  promise.then(() => { entry.pending = false; entry.at = Date.now(); }, () => { bwCache.delete(key); });
  return promise;
};

// One row per customer: earliest and latest completed appointment before 'to'. Only ids and dates come back.
const bwClientCache = window.__bwClientCache || (window.__bwClientCache = new Map());
const bwFetchClientRows = (to) => {
  const key = String(to);
  const hit = bwClientCache.get(key);
  if (hit && (hit.pending || Date.now() - hit.at < 60000)) return hit.promise;
  const promise = ctx.api.request({
    url: 'appointments:query',
    method: 'post',
    headers: { 'X-Timezone': '+00:00' },
    data: {
      measures: [{ field: ['startTime'], aggregation: 'min', alias: 'first' }, { field: ['startTime'], aggregation: 'max', alias: 'last' }],
      dimensions: [{ field: ['customerId'], alias: 'customerId' }],
      filter: { $and: [{ status: { $in: BW_QUALIFYING_STATUSES } }, { customerId: { $notEmpty: true } }, { startTime: { $lt: new Date(to).toISOString() } }] },
      limit: BW_QUERY_LIMIT,
    },
  }).then((res) => {
    const rows = (res && res.data && res.data.data) || [];
    if (rows.length >= BW_QUERY_LIMIT) throw new Error('Too many customers to analyse at once.');
    return rows.map((r) => ({ customerId: r.customerId, first: new Date(r.first).getTime(), last: new Date(r.last).getTime() }));
  });
  const entry = { promise, pending: true, at: Date.now() };
  bwClientCache.set(key, entry);
  promise.then(() => { entry.pending = false; entry.at = Date.now(); }, () => { bwClientCache.delete(key); });
  return promise;
};

