    h(Metric, { compact: oneCol, label: 'Paid transactions', value: !result || state.loading ? '…' : String(t.tx), sub: 'Payments received in this range' }),
    h(Metric, { compact: oneCol, label: 'Average per transaction', value: !result || state.loading ? '…' : (t.tx ? money(t.average) : '—'), sub: 'Total earnings ÷ paid transactions' }),
    h(Metric, { compact: oneCol, style: earnCols === 2 ? spanAll : null, label: 'Highest earnings (' + NOUN[grouping] + ')', accent: best ? token.colorWarningText : token.colorTextTertiary,
      value: !result || state.loading ? '…' : best ? money(best.net) : 'No earnings yet',
      sub: !result || state.loading ? '' : best ? best.longLabel + (best.partial ? ' (partial ' + NOUN[grouping] + ')' : '') : 'Nothing earned in this range' }));

  let chartBody;
  if (!cfg || (valid && state.loading)) chartBody = h('div', { style: { height: 260, display: 'flex', alignItems: 'center', justifyContent: 'center' } }, h(Spin, null));
  else if (!valid) chartBody = h(Empty, { image: Empty.PRESENTED_IMAGE_SIMPLE, description: rangeError || 'Choose a date range' });
  else if (state.error) chartBody = h(Alert, { type: 'error', showIcon: true, message: 'Could not load earnings', description: state.error,
    action: h(Button, { size: narrow ? 'middle' : 'small', onClick: () => { bwCache.clear(); setReload((x) => x + 1); } }, 'Retry') });
  else if (noEarnings) chartBody = h(Empty, { image: Empty.PRESENTED_IMAGE_SIMPLE, description: 'No earnings between ' + rangeText + '.' });
  else chartBody = h(BarChart, { data: result.periods, best, currency });

  const chart = h(Card, null,
    h('div', { style: { display: 'flex', flexWrap: 'wrap', gap: 8, alignItems: 'center', justifyContent: 'space-between', marginBottom: 10 } },
      h('div', { style: { minWidth: 0 } },
        h('div', { style: { fontWeight: 600 } }, 'Earnings by ' + NOUN[grouping]),
        best && !state.loading ? h('div', { style: { fontSize: 12, color: token.colorWarningText } }, '★ Highest Earnings: ' + money(best.net) + ' — ' + best.longLabel) : null),
      h(Segmented, { options: oneCol ? GROUPINGS_SHORT : GROUPINGS, value: grouping, onChange: setGrouping, 'aria-label': 'Group earnings by', size: ctlSize, block: narrow, style: narrow ? { width: '100%' } : undefined })),
    chartBody);

  const prevText = prevRange ? bwFmtRangeYear(prevRange.start, prevRange.end) : '';
  // Two clearly different hues: the theme's primary colour for New and a fixed teal for Returning
