  let retentionBody;
  if (!cfg) retentionBody = h('div', { style: { height: 120, display: 'flex', alignItems: 'center', justifyContent: 'center' } }, h(Spin, null));
  else if (!valid) retentionBody = h(Empty, { image: Empty.PRESENTED_IMAGE_SIMPLE, description: rangeError || 'Choose a date range' });
  else if (clients.error) retentionBody = h(Alert, { type: 'error', showIcon: true, message: 'Could not load client statistics', description: clients.error,
    action: h(Button, { size: narrow ? 'middle' : 'small', onClick: () => { bwClientCache.clear(); setReload((x) => x + 1); } }, 'Retry') });
  else {
    retentionBody = h('div', { style: { display: 'flex', flexDirection: 'column', gap: 12 } },
      h('div', { style: { display: 'grid', gridTemplateColumns: retCols === 1 ? 'minmax(0, 1fr)' : retCols === 2 ? 'repeat(2, minmax(0, 1fr))' : 'repeat(auto-fit, minmax(200px, 1fr))', gap: retCols ? 8 : 12 } },
        h(RetentionCard, { compact: narrow, label: 'New clients', color: cColors.new, loading: cLoading, count: cl ? cl.newClients : 0, pct: cl ? cl.newPct : null, prevCount: cp ? cp.newClients : 0, hint: 'First completed visit in this range' }),
        h(RetentionCard, { compact: narrow, label: 'Returning clients', color: cColors.returning, loading: cLoading, count: cl ? cl.returning : 0, pct: cl ? cl.returningPct : null, prevCount: cp ? cp.returning : 0, hint: 'Visited before this range too' }),
        h('div', { style: retCols === 2 ? { gridColumn: '1 / -1' } : null },
          h(RetentionCard, { compact: narrow, label: 'Total unique clients', loading: cLoading, count: cl ? cl.total : 0, prevCount: cp ? cp.total : 0, hint: 'Each client counted once' }))),
      cLoading ? h('div', { style: { height: 80, display: 'flex', alignItems: 'center', justifyContent: 'center' } }, h(Spin, null))
        : cl.total === 0 && cp.total === 0 ? h(Empty, { image: Empty.PRESENTED_IMAGE_SIMPLE, description: 'No completed appointments between ' + rangeText + ' or in the previous period.' })
          : h(RetentionBars, { colors: cColors, legendBelow: narrow, rows: [{ key: 'cur', title: 'This range', range: rangeText, data: cl }, { key: 'prev', title: 'Previous period', range: prevText, data: cp }] }));
  }
  const retention = h(Card, null,
    h('div', { style: { marginBottom: 10 } },
      h('div', { style: { fontWeight: 600 } }, 'New vs returning clients'),
      h('div', { style: { fontSize: 12, color: token.colorTextSecondary } }, valid ? rangeText + ' compared with ' + prevText : !cfg ? 'Loading…' : 'Choose a date range')),
    retentionBody);

  const earningsNote = h(Typography.Text, { type: 'secondary', style: { fontSize: 12 } },
    'Earnings are payments with status Paid (services, memberships, deposits and tips) minus Paid refunds, dated by payment date in ' + tzName +
    '. Pending, failed and refunded payments are not counted. Weeks start on ' + ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'][weekStart] + '; weeks and months at the edges include only days inside the range. When two periods tie, the earlier one is shown as highest.');
  const clientsNote = h(Typography.Text, { type: 'secondary', style: { fontSize: 12 } },
    'Clients: only completed appointments count as visits (scheduled, cancelled and no-show do not). A client is new if their first completed visit ever falls inside the range, otherwise returning. ' +
    'The previous period is the week or month before (cut to the same number of days so far for This Week and This Month), or the same number of days just before a custom range. Percentage change is the change in client count, not in share. All dates use ' + tzName + '.');

  const body = h('div', { ref: rootRef, style: { display: 'flex', flexDirection: 'column', gap: 12, minWidth: 0 } }, filters, ...(BW_VIEW === 'staff'
    ? [h(StaffPerformance, { inst, range, tz, currency, valid, rangeError, cfg, narrow, oneCol, ctlSize, rangeText, reload, setReload })]
