  const height = width < 520 ? 230 : 290;
  const padL = width < 520 ? 44 : 56; const padR = 8; const padT = 22; const padB = width < 520 ? 32 : 30;
  const innerW = Math.max(0, width - padL - padR); const innerH = height - padT - padB;
  const max = niceMax(Math.max(0, ...data.map((d) => d.net)));
  const min = Math.min(0, ...data.map((d) => d.net));
  const lo = min < 0 ? -niceMax(-min) : 0;
  const y = (v) => padT + innerH - ((v - lo) / (max - lo)) * innerH;
  const slot = data.length ? innerW / data.length : 0;
  const barW = Math.max(1, Math.min(56, slot * 0.72));
  const every = Math.max(1, Math.ceil(data.length / Math.max(1, Math.floor(innerW / (width < 520 ? 58 : 72)))));
  const ticks = [0, 0.25, 0.5, 0.75, 1].map((f) => lo + (max - lo) * f);
  const pick = (clientX) => {
    if (!wrap.current || !slot) return;
