    const i = Math.floor(x / slot);
    setHover(data.length ? Math.min(data.length - 1, Math.max(0, i)) : null); // edges count as the nearest bar
  };
  const tip = hover != null ? data[hover] : null;
  const bestIndex = best ? data.findIndex((d) => d.key === best.key) : -1;
  // Keyboard: focus the chart, then use the arrow keys (Home/End) to step through the periods.
  const onKeyDown = (e) => {
    if (!data.length) return;
    const cur = hover == null ? (bestIndex >= 0 ? bestIndex : 0) : hover;
    const next = e.key === 'ArrowRight' ? Math.min(data.length - 1, cur + 1) : e.key === 'ArrowLeft' ? Math.max(0, cur - 1) : e.key === 'Home' ? 0 : e.key === 'End' ? data.length - 1 : null;
    if (next == null) return;
