  };
  const tipW = Math.min(180, Math.max(120, width - 8));
  const summary = 'Earnings chart with ' + data.length + ' ' + NOUN[data.grouping] + (data.length === 1 ? '' : 's') + (best ? '. Highest: ' + best.longLabel + ', ' + bwMoney(best.net, currency) : '');
  return h('div', { ref: wrap, tabIndex: 0, role: 'group', 'aria-label': summary + '. Use the left and right arrow keys to read each ' + NOUN[data.grouping] + '.', onKeyDown,
    onFocus: () => { setFocused(true); if (hover == null) setHover(bestIndex >= 0 ? bestIndex : 0); }, onBlur: () => { setFocused(false); setHover(null); },
    style: { position: 'relative', width: '100%', minWidth: 0, touchAction: 'pan-y', outline: focused ? '2px solid ' + token.colorPrimary : 'none', outlineOffset: 2, borderRadius: 4 },
    onMouseMove: (e) => pick(e.clientX), onMouseLeave: () => { if (!focused) setHover(null); },
    onTouchStart: (e) => e.touches[0] && pick(e.touches[0].clientX), onTouchMove: (e) => e.touches[0] && pick(e.touches[0].clientX) },
  h('div', { style: BW_SR_ONLY }, h('table', null,
    h('caption', null, 'Earnings by ' + NOUN[data.grouping]),
    h('thead', null, h('tr', null, h('th', { scope: 'col' }, 'Period'), h('th', { scope: 'col' }, 'Earnings'), h('th', { scope: 'col' }, 'Paid payments'))),
    h('tbody', null, data.map((d) => h('tr', { key: d.key }, h('th', { scope: 'row' }, d.longLabel + (best && d.key === best.key ? ' (highest)' : '')), h('td', null, bwMoney(d.net, currency)), h('td', null, String(d.tx))))))),
  width > 0 ? h('svg', { width, height, 'aria-hidden': true, focusable: 'false', style: { display: 'block' } },
    ticks.map((t, i) => h('g', { key: 't' + i },
      h('line', { x1: padL, x2: width - padR, y1: y(t), y2: y(t), stroke: token.colorBorderSecondary, strokeDasharray: t === 0 ? null : '3 3' }),
      h('text', { x: padL - 6, y: y(t) + 4, textAnchor: 'end', fontSize: 11, fill: token.colorTextTertiary }, bwMoneyShort(t, currency)))),
    data.map((d, i) => {
      const isBest = best && d.key === best.key;
      const top = y(Math.max(0, d.net)); const bottom = y(Math.min(0, d.net));
      const x = padL + i * slot + (slot - barW) / 2;
      return h('g', { key: d.key },
        hover === i ? h('rect', { x: padL + i * slot, y: padT, width: slot, height: innerH, fill: token.colorFillTertiary }) : null,
        h('rect', { x, y: top, width: barW, height: Math.max(d.net === 0 ? 0 : 1, bottom - top), rx: Math.min(3, barW / 3),
          fill: isBest ? token.colorWarning : token.colorPrimary, fillOpacity: isBest ? 1 : 0.75 }),
        d.net === 0 ? h('rect', { x, y: y(0) - 1, width: barW, height: 2, fill: token.colorBorder }) : null,
        isBest ? h('text', { x: x + barW / 2, y: top - 6, textAnchor: 'middle', fontSize: 11, fontWeight: 600, fill: token.colorWarningText }, '★ ' + bwMoneyShort(d.net, currency)) : null,
        i % every === 0 ? h('text', { x: padL + i * slot + slot / 2, y: height - padB + (width < 520 ? 19 : 16), textAnchor: 'middle', fontSize: 11, fill: token.colorTextSecondary }, d.label) : null);
    })) : null,
