// Change versus the previous period. Arrows show direction only; colours stay neutral because a rise or
// fall is not automatically good or bad (more new clients is not the same as better retention).
function ChangeLine({ cur, prev }) {
  const { token } = theme.useToken();
  const c = bwChange(cur, prev);
  const unit = Math.abs(c.diff) === 1 ? 'client' : 'clients';
  const fmtN = (n) => (n > 0 ? '+' : n < 0 ? '−' : '') + Math.abs(n);
  const fmtP = (p) => (p > 0 ? '+' : p < 0 ? '−' : '') + Math.abs(p).toFixed(1) + '%';
  let arrow; let text; let tone;
  if (c.diff === 0) { arrow = '—'; text = 'No change'; tone = token.colorTextSecondary; } else {
    arrow = c.diff > 0 ? '▲' : '▼';
    text = fmtN(c.diff) + ' ' + unit + (c.pct == null ? ' (N/A)' : ' (' + fmtP(c.pct) + ')');
    tone = c.diff > 0 ? token.colorInfoText : token.colorText;
  }
  return h('div', { style: { fontSize: 12, marginTop: 6, display: 'flex', gap: 6, alignItems: 'baseline', flexWrap: 'wrap' } },
    h('span', { style: { display: 'inline-flex', alignItems: 'baseline', gap: 4, padding: '1px 6px', borderRadius: 4, background: token.colorFillSecondary, color: tone, fontWeight: 600 } }, h('span', { 'aria-hidden': true }, arrow), text),
    h('span', { style: { color: token.colorTextTertiary } }, 'vs ' + prev + ' before'));
}

